                <div className={lpMain.progress_word}>
                    <div className={lpMain.progress_0}>
                        <p id="wordNumber">10</p>
                        <p>0% - 24%</p>
                    </div>
                    <div className={lpMain.progress_1}>
                        <p id="wordNumber">10</p>
                        <p>25% - 49%</p>
                    </div>
                    <div className={lpMain.progress_2}>
                        <p id="wordNumber">10</p>
